import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G), {k:(len(v),len(v[0])) for k,v in G.items()})
os.makedirs('programs',exist_ok=True)
json.dump([{'input':G['Demo pair 1 input'],'output':G['Demo pair 1 output']}],open('programs/task-6b6093e2.json','w'))

def transform(g):
    H,W=len(g),len(g[0])
    pluses=[]  # (r,c,color,cells)
    occ={}
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if r>0 and r<H-1 and c>0 and c<W-1:
                nb=[g[r-1][c],g[r+1][c],g[r][c-1],g[r][c+1]]
                if all(x==3 for x in nb):
                    if v!=0: pluses.append((r,c,v,[(r-1,c),(r+1,c),(r,c-1),(r,c+1)]))
                    elif v==0: pluses.append((r,c,0,[(r-1,c),(r+1,c),(r,c-1),(r,c+1)]))
    for i,(r,c,v,arms) in enumerate(pluses):
        for cell in arms+[(r,c)]: occ[cell]=i
    out=[[0]*W for _ in range(H)]
    def ray(i,r0,c0,dr,dc,color):
        r,c=r0+dr,c0+dc
        while 0<=r<H and 0<=c<W:
            if (r,c) in occ and occ[(r,c)]!=i: return
            out[r][c]=color
            r+=dr; c+=dc
    order=sorted(range(len(pluses)),key=lambda i:pluses[i][2]==0)  # colored first
    for phase in (0,1):
        for i in order:
            r0,c0,v,_=pluses[i]
            if phase==0: ray(i,r0,c0,0,-1,v); ray(i,r0,c0,0,1,v)
            else: ray(i,r0,c0,-1,0,v); ray(i,r0,c0,1,0,v)
    for i,(r0,c0,v,arms) in enumerate(pluses):
        for (r,c) in arms: out[r][c]=3
        if v!=0: out[r0][c0]=v
    return out
d=G['Demo pair 1 input']; o=G['Demo pair 1 output']
res=transform(d)
print(res==o)
if res!=o:
    for r in range(len(o)):
        if res[r]!=o[r]: print(r,'got',res[r],'\n exp',o[r])

